define(["theme_boost/drawers"], function(Drawers) {
    "use strict";
    const focusableSelector = 'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])';
    return {
        init: function() {
            const navigations = Array.from(document.querySelectorAll('.ec-mega-navigation'));
            const positionPanel = navigation => {
                navigation.style.setProperty('--ec-mega-panel-top', `${Math.round(navigation.getBoundingClientRect().bottom)}px`);
            };
            const closeNavigation = navigation => {
                navigation.querySelectorAll('.ec-mega-trigger').forEach(button => {
                    button.classList.remove('active');
                    button.setAttribute('aria-selected', 'false');
                    button.setAttribute('tabindex', '-1');
                });
                navigation.querySelectorAll('.ec-mega-panel').forEach(panel => panel.classList.remove('active', 'show'));
                try {
                    window.localStorage.setItem('theme_echealth_navigation_active_section', '');
                } catch (error) {
                    // Closing the panel must keep working when storage is unavailable.
                }
            };
            const hasHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches;

            navigations.forEach(navigation => {
                const buttons = Array.from(navigation.querySelectorAll('.ec-mega-trigger'));
                const hascurrentpage = navigation.querySelector('.ec-mega-panel a[aria-current="page"]') !== null;
                let remembered;
                try {
                    remembered = window.localStorage.getItem('theme_echealth_navigation_active_section');
                } catch (error) {
                    // Use the server-provided active state when storage is unavailable.
                }
                buttons.forEach(button => {
                    button.addEventListener('shown.bs.tab', () => {
                        const section = Array.from(button.classList).find(name => name.startsWith('ec-nav-group--'))?.replace('ec-nav-group--', '');
                        try {
                            window.localStorage.setItem('theme_echealth_navigation_active_section', section || '');
                        } catch (error) {
                            // Bootstrap tab interaction remains available when storage is disabled.
                        }
                    });
                });

                if (!hascurrentpage && remembered) {
                    const rememberedbutton = buttons.find(button => button.classList.contains(`ec-nav-group--${remembered}`));
                    if (rememberedbutton && !rememberedbutton.classList.contains('active')) {
                        rememberedbutton.click();
                    }
                }

                positionPanel(navigation);
                navigation.addEventListener('pointerleave', event => {
                    if (hasHover && event.pointerType === 'mouse') {
                        closeNavigation(navigation);
                    }
                });
                navigation.addEventListener('focusout', event => {
                    if (!navigation.contains(event.relatedTarget)) {
                        closeNavigation(navigation);
                    }
                });
                navigation.addEventListener('wheel', () => closeNavigation(navigation), {passive: true});
            });

            window.addEventListener('resize', () => navigations.forEach(positionPanel), {passive: true});
            document.addEventListener('click', event => {
                if (!(event.target instanceof Element) || !event.target.closest('.ec-mega-navigation')) {
                    navigations.forEach(closeNavigation);
                }
            });
            document.addEventListener('scroll', () => navigations.forEach(closeNavigation), {capture: true, passive: true});
            window.addEventListener('scroll', () => navigations.forEach(closeNavigation), {passive: true});

            document.querySelectorAll('[data-ec-accordion]').forEach(details => {
                if (details.classList.contains('ec-mega-group')) {
                    return;
                }
                const label = details.querySelector(':scope > summary')?.textContent?.trim().replace(/\s+/g, ' ');
                if (!label) {
                    return;
                }
                const key = `theme_echealth_navigation_${details.dataset.ecAccordion}_${label}`;
                const active = details.querySelector('a[aria-current="page"]') !== null;
                try {
                    const saved = window.localStorage.getItem(key);
                    if (active) {
                        details.open = true;
                    } else if (saved !== null) {
                        details.open = saved === 'open';
                    }
                } catch (error) {
                    // Native disclosure still works when browser storage is disabled.
                }
                details.addEventListener('toggle', () => {
                    try {
                        window.localStorage.setItem(key, details.open ? 'open' : 'closed');
                    } catch (error) {
                        // Native disclosure still works when browser storage is disabled.
                    }
                });
            });

            document.addEventListener('keydown', event => {
                if (event.key === 'Escape') {
                    navigations.forEach(navigation => {
                        const activebutton = navigation.querySelector('.ec-mega-trigger.active');
                        const activepanel = activebutton && document.getElementById(activebutton.getAttribute('aria-controls'));
                        const shouldrestorefocus = activepanel?.contains(document.activeElement);
                        closeNavigation(navigation);
                        if (shouldrestorefocus) {
                            activebutton.focus();
                        }
                    });
                }
            });

            const drawer = document.getElementById('theme_boost-drawers-primary');
            const toggle = document.querySelector('[data-target="theme_boost-drawers-primary"][data-action="toggle"]');
            if (!drawer || !toggle) {
                return;
            }
            const focusableElements = () => Array.from(drawer.querySelectorAll(focusableSelector))
                .filter(element => !element.hasAttribute('hidden') && element.getClientRects().length > 0);
            const syncState = () => {
                const open = drawer.classList.contains('show');
                toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
                if (open) {
                    drawer.setAttribute('role', 'dialog');
                    drawer.setAttribute('aria-modal', 'true');
                    drawer.setAttribute('aria-label', drawer.querySelector('.ec-navigation')?.getAttribute('aria-label') || 'Main navigation');
                } else {
                    drawer.removeAttribute('role');
                    drawer.removeAttribute('aria-modal');
                    drawer.removeAttribute('aria-label');
                }
            };
            drawer.addEventListener(Drawers.eventTypes.drawerShown, syncState);
            drawer.addEventListener(Drawers.eventTypes.drawerHidden, syncState);
            syncState();
            document.addEventListener('keydown', event => {
                if (!drawer.classList.contains('show')) {
                    return;
                }
                if (event.key === 'Escape') {
                    event.preventDefault();
                    Drawers.getDrawerInstanceForNode(drawer).closeDrawer();
                    return;
                }
                if (event.key !== 'Tab') {
                    return;
                }
                const focusable = focusableElements();
                if (!focusable.length) {
                    event.preventDefault();
                    drawer.focus();
                    return;
                }
                const first = focusable[0];
                const last = focusable[focusable.length - 1];
                if (event.shiftKey && (document.activeElement === first || !drawer.contains(document.activeElement))) {
                    event.preventDefault();
                    last.focus();
                } else if (!event.shiftKey && (document.activeElement === last || !drawer.contains(document.activeElement))) {
                    event.preventDefault();
                    first.focus();
                }
            });
            document.addEventListener('focusin', event => {
                if (!drawer.classList.contains('show') || drawer.contains(event.target) || event.target === toggle) {
                    return;
                }
                event.stopImmediatePropagation();
                const first = focusableElements()[0];
                if (first) {
                    first.focus();
                }
            }, true);
        }
    };
});
